async def keyword_clientContactPreference_connector(payload: dict) -> JSONResponse:
    """
    Handles keyword-based opt-in/opt-out for marketing notifications by updating
    client contact preferences in the database via the standard CRUD SP.
    This is an internal hook called from the WhatsApp inbound webhook.
    """
    with workflow_step("ProcessKeywordContactPreference", workflow_name="ClientContactPreference"):
        try:
            company_id = payload.get("companyId")
            client_id = payload.get("clientId")
            channel = payload.get("channel")  # e.g., "whatsapp"
            keyword = payload.get("keyword", "").upper()  # BAJA, ALTA, STOP, CANCELAR
            source = payload.get("source", "whatsapp_keyword")
            updated_by_user_id = payload.get("updatedByUserId") # Optional

            if not company_id or not client_id or not channel:
                log_workflow_step("ValidationFailed", {"reason": "Missing required fields", "payload_keys": list(payload.keys())})
                return JSONResponse(
                    content={
                        "error": "companyId, clientId, and channel are required for contact preference update"
                    },
                    status_code=400,
                )

            marketing_opt_in = None # Undefined initially
            opted_in_at = None
            opted_out_at = None
            current_time_iso = datetime.utcnow().isoformat() + "Z"

            if keyword in ["BAJA", "STOP", "ALTO", "CANCELAR"]:
                marketing_opt_in = False
                opted_out_at = current_time_iso
                log_workflow_step("OptOutKeywordDetected", {"clientId": client_id, "channel": channel, "keyword": keyword})
            elif keyword == "ALTA":
                marketing_opt_in = True
                opted_in_at = current_time_iso
                log_workflow_step("OptInKeywordDetected", {"clientId": client_id, "channel": channel, "keyword": keyword})
            else:
                # No relevant keyword, return without making changes
                log_workflow_step("NoRelevantKeyword", {"clientId": client_id, "channel": channel, "keyword": keyword})
                return JSONResponse(
                    content={
                        "message": "No relevant keyword detected for contact preference update."
                    },
                    status_code=200,
                )

            # Prepare payload for the CRUD SP (action 1 for upsert logic)
            json_for_sp = {
                "clientContactPreferences": [{
                    "action": 1,  # Upsert action
                    "companyId": company_id,
                    "clientId": client_id,
                    "channel": channel,
                    "marketingOptIn": marketing_opt_in,
                    "source": source,
                    "optedInAt": opted_in_at,
                    "optedOutAt": opted_out_at,
                    "updatedByUserId": updated_by_user_id, # Pass if provided
                    "active": True, # Assume active when setting preference
                }]
            }

            # Call the standard CRUD SP for persistence
            # This connector interacts with the database; no external HTTP service call here.
            with timed_integration("database", "sp_clientContactPreferences_upsert") as span:
                sp_response = clientContactPreferences_sp(json_for_sp)
                # Avoid logging full payload if it contains PII, log only status/summary
                span.response = {"status_code": sp_response.status_code} 
                span.http_status = sp_response.status_code

            if sp_response.status_code != 200:
                log_workflow_step("DatabaseUpdateFailed", {"error_detail": json.loads(sp_response.body) if isinstance(sp_response.body, bytes) else sp_response.body, "payload_sent_summary": {"action":1, "companyId":company_id, "clientId":client_id, "channel":channel, "marketingOptIn":marketing_opt_in}})
                return sp_response  # Return the error from the SP call directly

            # Extract response fields as per gate_result's mandatory_constraints
            # Assuming the SP response contains the updated entity details or an ID
            response_data_content = json.loads(sp_response.body) if isinstance(sp_response.body, bytes) else sp_response.body

            # The SP will return 'value' (the ID) and 'msg'. We need to build the requested response structure.
            # The sp_clientContactPreferences will return the 'value' of the ID on success (or the existing ID).
            client_contact_preference_id = response_data_content.get("result", [{}])[0].get("value") if response_data_content.get("result") else None

            final_response = {
                "clientContactPreferenceId": client_contact_preference_id,
                "clientId": client_id,
                "channel": channel,
                "marketingOptIn": marketing_opt_in,
                "source": source,
                "optedInAt": opted_in_at,
                "optedOutAt": opted_out_at,
                "updatedByUserId": updated_by_user_id,
                "active": True,
            }
            log_workflow_step("PreferenceUpdated", {"clientId": client_id, "channel": channel, "optInStatus": marketing_opt_in})
            return JSONResponse(content=final_response, status_code=200)

        except Exception as e:
            log_workflow_step("ConnectorError", {"error": str(e)})
            return JSONResponse(content={
                "error": str(e),
                "message": "An unexpected error occurred during contact preference update."
            }, status_code=500)
