export interface ClientContactPreference {
  clientContactPreferenceId: number;
  companyId: number;
  clientId: number;
  channel: string;
  marketingOptIn: boolean;
  source: string;
  optedInAt: string | null;
  optedOutAt: string | null;
  updatedByUserId: number | null;
  active: boolean;
  created_At: string;
  updated_at: string | null;
}

export interface ClientContactPreferenceListResponse {
  clientContactPreferences: ClientContactPreference[];
}

// GET ALL — POST /all_clientContactPreferences
export async function getAllClientContactPreferences(companyId: number, clientId?: number): Promise<ClientContactPreference[]> {
  const payload: { companyId: number; clientId?: number }[] = [{ companyId }];
  if (clientId !== undefined) {
    payload[0].clientId = clientId;
  }

  const res = await fetch(BASE_URL + "/all_clientContactPreferences", {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ clientContactPreferences: payload }),
  });
  if (!res.ok) throw new Error(await res.text());
  const data: ClientContactPreferenceListResponse = await res.json();
  return data.clientContactPreferences ?? [];
}

// CREATE — action: 1
export async function createClientContactPreference(payload: Omit<ClientContactPreference, "clientContactPreferenceId" | "created_At" | "updated_at">): Promise<ClientContactPreference> {
  const res = await fetch(BASE_URL + "/clientContactPreferences", {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ clientContactPreferences: [{ action: 1, ...payload }] }),
  });
  if (!res.ok) throw new Error(await res.text());
  return await res.json();
}

// UPDATE — action: 2
export async function updateClientContactPreference(id: number, payload: Partial<Omit<ClientContactPreference, "clientContactPreferenceId" | "created_At" | "updated_at">>): Promise<ClientContactPreference> {
  const res = await fetch(BASE_URL + "/clientContactPreferences", {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ clientContactPreferences: [{ action: 2, clientContactPreferenceId: id, ...payload }] }),
  });
  if (!res.ok) throw new Error(await res.text());
  return await res.json();
}

// DELETE — action: 3
export async function deleteClientContactPreference(id: number, companyId: number): Promise<void> {
  const res = await fetch(BASE_URL + "/clientContactPreferences", {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ clientContactPreferences: [{ action: 3, clientContactPreferenceId: id, companyId: companyId }] }),
  });
  if (!res.ok) throw new Error(await res.text());
}
