import { useIonViewWillEnter } from '@ionic/react';
import { useUser } from '../../../contexts/UserContext';
import { useToast } from '../../../hooks/useToast';
import { onDataChanged, notifyDataChanged } from '../../../utils/refreshBus';
import {
  getAllClientContactPreferences,
  createClientContactPreference,
  updateClientContactPreference,
  ClientContactPreference,
} from '../../../api/clientContactPreferenceApi';
import { InputChangeEventDetail, ToggleChangeEventDetail } from '@ionic/core'; // Explicitly import types

export const useClientContactPreference = () => {
  const { companyId, userId, clientId } = useUser();
  const { showToast, toastProps } = useToast();
  const [preferences, setPreferences] = useState<ClientContactPreference[]>([]);
  const [loading, setLoading] = useState(false);
  const [savingChannel, setSavingChannel] = useState<string | null>(null);

  const loadPreferences = useCallback(async () => {
    if (!companyId || !clientId) return;
    setLoading(true);
    try {
      const data = await getAllClientContactPreferences(companyId, clientId);
      setPreferences(data);
    } catch (err) {
      showToast((err as Error).message ?? 'Error al cargar preferencias de contacto', 'danger');
    } finally {
      setLoading(false);
    }
  }, [companyId, clientId, showToast]);

  const handleToggleChange = useCallback(async (
    channel: string,
    newOptInStatus: ToggleChangeEventDetail['checked'],
    existingPreferenceId: number | undefined
  ) => {
    if (!companyId || !clientId) {
      showToast('Error: Company ID o Client ID no disponibles.', 'danger');
      return;
    }

    setSavingChannel(channel);
    try {
      const now = new Date().toISOString();
      const basePayload = {
        companyId,
        clientId,
        channel,
        marketingOptIn: newOptInStatus,
        source: 'admin_ui',
        updatedByUserId: userId,
        active: true, // Always active when setting preference
      };

      if (newOptInStatus) {
        // Opting in
        Object.assign(basePayload, { optedInAt: now, optedOutAt: null });
      } else {
        // Opting out
        Object.assign(basePayload, { optedInAt: null, optedOutAt: now });
      }

      let updatedPref: ClientContactPreference;
      if (existingPreferenceId) {
        updatedPref = await updateClientContactPreference(existingPreferenceId, basePayload);
      } else {
        updatedPref = await createClientContactPreference(basePayload);
      }

      setPreferences(prev => {
        const existingIndex = prev.findIndex(p => p.clientContactPreferenceId === updatedPref.clientContactPreferenceId);
        if (existingIndex > -1) {
          const newPreferences = [...prev];
          newPreferences[existingIndex] = updatedPref;
          return newPreferences;
        } else {
          return [...prev, updatedPref];
        }
      });
      showToast('Preferencia de contacto actualizada con éxito', 'success');
      notifyDataChanged('clientContactPreference-saved');
    } catch (err) {
      showToast((err as Error).message ?? 'Error al actualizar preferencia de contacto', 'danger');
    } finally {
      setSavingChannel(null);
    }
  }, [companyId, clientId, userId, showToast]);

  useEffect(() => {
    loadPreferences();
  }, [loadPreferences]);

  useIonViewWillEnter(() => {
    loadPreferences();
  });

  useEffect(() => onDataChanged(() => loadPreferences()), [loadPreferences]);

  return {
    preferences,
    loading,
    savingChannel,
    toastProps,
    handleToggleChange,
  };
};

export type ClientContactPreferenceVM = ReturnType<typeof useClientContactPreference>;
